function renderDayPanel(date,current,transactionsLocked){const group=currentGroup(),active=group.expenses.filter(expense=>expense.date===date),deleted=state.activeMemberId===ACCOUNTANT_ID?(group.deletedExpenses||[]).filter(expense=>expense.date===date):[],expenses=[...active,...deleted],total=active.filter(expense=>!expense.isDraft).reduce((sum,expense)=>sum+expense.amount,0),dayNumber=dayDistance(group.tripStartDate,date)+1,isToday=date===current;const periods=[{id:"morning",label:"Morning",icon:"☀"},{id:"afternoon",label:"Afternoon",icon:"◐"},{id:"evening",label:"Evening",icon:"☾"}];return `<article class="day-panel"><div class="day-header"><div class="date-box"><strong>${fromDateKey(date).getDate()}</strong><span>${formatDate(date,{month:"short"})}</span></div><div><small>DAY ${dayNumber}${isToday&&!group.tripEndDate?" · TODAY":""}</small><h3>${formatDate(date)}</h3></div><div class="day-total"><small>DAY TOTAL</small><strong>${money(total)}</strong></div></div><div class="day-periods">${periods.map(period=>renderPeriod(date,period,expenses,transactionsLocked)).join("")}</div></article>`}
