function renderExpenseFormMembers(){const members=currentGroup().members;$("#payer-list").innerHTML=members.map(member=>`<button type="button" data-payer-id="${member.id}" role="radio" aria-checked="false" aria-label="${escapeHtml(member.name)}" title="${escapeHtml(member.name)}">${memberInitials(member.name)}</button>`).join("");$("#payer-list").querySelectorAll("button").forEach(button=>button.addEventListener("click",()=>setPayer(button.dataset.payerId)));setPayer(members.some(member=>member.id===state.activeMemberId)?state.activeMemberId:members[0].id);$("#split-list").innerHTML=members.map(member=>`<div class="split-person active" data-split-member="${member.id}"><button class="split-person-toggle" type="button" aria-pressed="true" aria-label="Include ${escapeHtml(member.name)} in the split"><span class="split-check" aria-hidden="true">✓</span><span class="mini-avatar" aria-hidden="true">${memberInitials(member.name)}</span><strong>${escapeHtml(member.name)}</strong></button><div class="allocation-input"><span>₱</span><input type="text" inputmode="decimal" data-share-member="${member.id}" value="" aria-label="${escapeHtml(member.name)} share" autocomplete="off"></div></div>`).join("");$("#split-list").querySelectorAll(".split-person-toggle").forEach(button=>button.addEventListener("click",()=>toggleSplitPerson(button)));$("#split-list").querySelectorAll("[data-share-member]").forEach(input=>{attachMoneyInput(input);input.addEventListener("input",()=>{splitSharesCustomized=true;manualShareIds.add(input.dataset.shareMember);hideError("#expense-error");redistributeRemainingShares(input)})});manualShareIds.clear();splitSharesCustomized=false;redistributeEqualShares()}
