function redistributeEqualShares(){const rows=selectedSplitRows(),parsedAmount=parseMoneyToCents($("#expense-amount").value),hasAmount=Number.isFinite(parsedAmount)&&parsedAmount>0,amount=hasAmount?parsedAmount:0,base=rows.length?Math.floor(amount/rows.length):0,remainder=rows.length?amount-base*rows.length:0;$("#split-list").querySelectorAll(".split-person").forEach(row=>{const input=row.querySelector("[data-share-member]"),index=rows.indexOf(row),share=index<0?0:base+(index<remainder?1:0);input.value=hasAmount?formatOptionalCentsForInput(share):"";input.disabled=index<0});manualShareIds.clear();splitSharesCustomized=false;updateSplitPreview()}
