function openExpenseForm(date,period="morning",expense=null){if(currentGroupIsReadOnly())return;expenseDate=date;expensePeriodName=period;editingExpenseId=expense?.id||null;$("#expense-date-label").textContent=`${formatDate(date)} · ${period}`.toUpperCase();$("#expense-title").textContent=expense?.isDraft?"Edit draft":expense?"Edit expense":"Add an expense";$("#save-draft-button").textContent=expense?.isDraft?"Update draft":"Save draft";$("#save-expense-button").innerHTML=`${expense&&!expense.isDraft?"Update":"Save"} expense <span>→</span>`;$("#expense-modal").hidden=false;document.body.classList.add("modal-open");if(expense)fillExpenseForm(expense);if(window.matchMedia("(hover: hover) and (pointer: fine)").matches)$("#expense-description").focus()}
