function updateSplitPreview(){const rows=selectedSplitRows(),parsedAmount=parseMoneyToCents($("#expense-amount").value),amount=Number.isFinite(parsedAmount)?parsedAmount:0,sum=rows.reduce((total,row)=>{const cents=parseMoneyToCents(row.querySelector("[data-share-member]").value);return total+(Number.isFinite(cents)?cents:0)},0),difference=amount-sum,preview=$("#split-preview");preview.classList.toggle("valid",amount>0&&difference===0);preview.classList.toggle("invalid",amount>0&&difference!==0);preview.textContent=!rows.length?"Choose someone":!amount?`${rows.length} selected`:difference===0?"Balanced":difference<0?"Shares exceed total":"Shares do not match total"}
function buildShares(amount){const shares=selectedSplitRows().map(row=>{const input=row.querySelector("[data-share-member]");return{id:input.dataset.shareMember,amount:parseMoneyToCents(input.value)}});if(!shares.length)return{error:"Choose at least one person."};if(shares.some(share=>!Number.isFinite(share.amount)||share.amount<0))return{error:"Enter a valid share for each selected person."};const total=shares.reduce((sum,share)=>sum+share.amount,0);if(total!==amount)return{error:`Shares must add up to ${money(amount)}. ${money(total)} is currently allocated.`};const base=Math.floor(amount/shares.length),remainder=amount-base*shares.length,isEqual=shares.every((share,index)=>share.amount===base+(index<remainder?1:0));return{shares,mode:isEqual?"equal":"unequal"}}
