function saveExpense(event,isDraft=false){event.preventDefault();if(currentGroupIsReadOnly())return closeExpenseForm();const group=currentGroup(),rawDescription=$("#expense-description").value.trim(),parsedAmount=parseMoneyToCents($("#expense-amount").value),description=isDraft?(rawDescription||"Untitled expense"):rawDescription,amount=isDraft?(Number.isFinite(parsedAmount)&&parsedAmount>=0?parsedAmount:0):parsedAmount;if(!isDraft&&!description)return showError("#expense-error","Add a description.");if(!isDraft&&(!Number.isFinite(amount)||amount<1))return showError("#expense-error","Enter a valid amount greater than zero.");if(expenseDate>simulatedToday(group))return showError("#expense-error","Future expenses are not allowed.");const result=isDraft?buildDraftShares(amount):buildShares(amount);if(result.error)return showError("#expense-error",result.error);const participantIds=result.shares.map(share=>share.id),existing=group.expenses.find(expense=>expense.id===editingExpenseId),viewer=currentViewerSnapshot(group),action=isDraft?(!existing||!existing.isDraft?"drafted":"updated"):(!existing||existing.isDraft?"recorded":"updated"),recordedAsId=existing?existing.recordedAsId||null:viewer.id,recordedAsName=existing?existing.recordedAsName||null:viewer.name,activityLog=appendViewerActivity(existing,action,viewer);const record={id:existing?.id||makeId(),date:expenseDate,period:expensePeriodName,description,amount,payerId:$("#expense-payer").value,participantIds,shares:result.shares,splitMode:result.mode,splitDetails:null,isDraft,recordedAsId,recordedAsName,activityLog,createdAt:existing?.createdAt||new Date()};if(existing)group.expenses=group.expenses.map(expense=>expense.id===existing.id?record:expense);else group.expenses.unshift(record);saveState();closeExpenseForm();renderTimeline();renderBalances()}
