function getBalances(){return groupBalances(currentGroup())}
function getViewerRelations(){const group=currentGroup(),viewerId=state.activeMemberId,relations=new Map(group.members.filter(member=>member.id!==viewerId).map(member=>[member.id,{lent:0,owes:0}]));group.expenses.filter(expense=>!expense.isDraft).forEach(expense=>{if(expense.payerId===viewerId){expense.shares.forEach(share=>{if(share.id!==viewerId&&relations.has(share.id))relations.get(share.id).lent+=share.amount})}else{const viewerShare=expense.shares.find(share=>share.id===viewerId)?.amount||0;if(viewerShare&&relations.has(expense.payerId))relations.get(expense.payerId).owes+=viewerShare}});return relations}
