function summarySection(label,items,emptyMessage){return `<section class="summary-balance-section"><small>${label}</small><div class="summary-balance-items">${items.length?items.join(""):`<span class="viewer-settled">${emptyMessage}</span>`}</div></section>`}
function relationSummaryItem(debtorId,creditorId,label,amount,tone){return `<button class="balance-item relation-summary-button" type="button" data-relation-debtor="${debtorId}" data-relation-creditor="${creditorId}"><span><strong>${label}</strong></span><b class="${tone}">${money(amount)}</b></button>`}
function renderComputationDetails(details){const groups=new Map();details.forEach(item=>{if(!groups.has(item.expense.date))groups.set(item.expense.date,[]);groups.get(item.expense.date).push(item)});return [...groups].map(([date,items])=>`<section class="relation-date-group"><h3>${formatDate(date,{weekday:"short",month:"short",day:"numeric",year:"numeric"})}</h3><div>${items.map(item=>`<div class="relation-detail-row"><strong>${escapeHtml(item.expense.description)}</strong><b>${money(item.amount)}</b></div>`).join("")}</div></section>`).join("")}
function renderDuplicateDetails(expenses){const group=currentGroup(),groups=new Map();expenses.forEach(expense=>{if(!groups.has(expense.date))groups.set(expense.date,[]);groups.get(expense.date).push(expense)});return [...groups].map(([date,items])=>`<section class="relation-date-group"><h3>${formatDate(date,{weekday:"short",month:"short",day:"numeric",year:"numeric"})}</h3><div>${items.map(expense=>{const payer=group.members.find(member=>member.id===expense.payerId),shares=expense.shares.map(share=>{const member=group.members.find(item=>item.id===share.id);return member?`${escapeHtml(member.name)} ${money(share.amount)}`:""}).filter(Boolean).join(" · ");return `<div class="relation-detail-row duplicate-detail-row"><span><strong>${escapeHtml(expense.description)}</strong><small>Paid by ${escapeHtml(payer?.name||"Member")} · ${shares}</small></span><b>${money(expense.amount)}</b></div>`}).join("")}</div></section>`).join("")}
function openDuplicateSummary(expenseId){const expense=currentGroup().expenses.find(item=>item.id===expenseId);if(!expense)return;const matches=[expense,...potentialDuplicates(expense)].sort((a,b)=>a.date.localeCompare(b.date)||new Date(a.createdAt)-new Date(b.createdAt));$("#relation-kicker").textContent="DUPLICATE AUDIT";$("#relation-title").textContent="Possible duplicate expenses";$("#relation-total").textContent=`${matches.length} matching entries`;$("#relation-details").innerHTML=renderDuplicateDetails(matches);$("#relation-modal").hidden=false;document.body.classList.add("modal-open");$("#close-relation").focus()}
function openRelationSummary(debtorId,creditorId){const group=currentGroup(),debtor=group.members.find(member=>member.id===debtorId),creditor=group.members.find(member=>member.id===creditorId);if(!debtor||!creditor)return;const details=group.expenses.filter(expense=>!expense.isDraft&&expense.payerId===creditorId).map(expense=>({expense,amount:expense.shares.find(share=>share.id===debtorId)?.amount||0})).filter(item=>item.amount>0).sort((a,b)=>a.expense.date.localeCompare(b.expense.date)||new Date(a.expense.createdAt)-new Date(b.expense.createdAt)),total=details.reduce((sum,item)=>sum+item.amount,0);$("#relation-kicker").textContent="INTER-PERSON COMPUTATION";$("#relation-title").textContent=`${debtor.name} owes ${creditor.name}`;$("#relation-total").textContent=money(total);$("#relation-details").innerHTML=renderComputationDetails(details);$("#relation-modal").hidden=false;document.body.classList.add("modal-open");$("#close-relation").focus()}
function openMemberShareSummary(memberId){const group=currentGroup(),member=group.members.find(item=>item.id===memberId);if(!member)return;const details=group.expenses.filter(expense=>!expense.isDraft).map(expense=>({expense,amount:expense.shares.find(share=>share.id===memberId)?.amount||0})).filter(item=>item.amount>0).sort((a,b)=>a.expense.date.localeCompare(b.expense.date)||new Date(a.expense.createdAt)-new Date(b.expense.createdAt)),total=details.reduce((sum,item)=>sum+item.amount,0);$("#relation-kicker").textContent="SHARE COMPUTATION";$("#relation-title").textContent=`${member.name}’s expense share`;$("#relation-total").textContent=money(total);$("#relation-details").innerHTML=renderComputationDetails(details);$("#relation-modal").hidden=false;document.body.classList.add("modal-open");$("#close-relation").focus()}
function closeRelationSummary(){$("#relation-modal").hidden=true;document.body.classList.remove("modal-open")}
function renderSpendingBreakdown(){const group=currentGroup(),posted=group.expenses.filter(expense=>!expense.isDraft),balances=getBalances();$("#spending-breakdown").innerHTML=group.members.map(member=>{const paid=posted.filter(expense=>expense.payerId===member.id).reduce((sum,expense)=>sum+expense.amount,0),share=posted.reduce((sum,expense)=>sum+(expense.shares.find(item=>item.id===member.id)?.amount||0),0),balance=balances.get(member.id)||0,label=member.id===state.activeMemberId?`You (${member.name})`:member.name,balanceLabel=balance>0?"Gets back":balance<0?"Owes":"Settled",tone=balance>0?"positive":balance<0?"negative":"neutral",balanceTag=balance?`button type="button" data-member-balance="${member.id}"`:`div`;return `<article class="member-summary-card"><div class="member-summary-avatar">${memberInitials(member.name)}</div><div class="member-summary-person"><strong>${escapeHtml(label)}</strong><span>Paid ${money(paid)}</span></div><button class="spending-share-button" type="button" data-share-summary="${member.id}"><small>Share</small><b>${money(share)}</b></button><${balanceTag} class="member-summary-balance"><small>${balanceLabel}</small><b class="${tone}">${money(Math.abs(balance))}</b></${balance?"button":"div"}></article>`}).join("");$("#spending-breakdown").querySelectorAll("[data-share-summary]").forEach(button=>button.addEventListener("click",()=>openMemberShareSummary(button.dataset.shareSummary)));$("#spending-breakdown").querySelectorAll("[data-member-balance]").forEach(button=>button.addEventListener("click",()=>openMemberBalanceSummary(button.dataset.memberBalance)))}
function renderBalances(){const group=currentGroup(),balances=getBalances(),interItems=[],consolidatedItems=[];renderSpendingBreakdown();if(state.activeMemberId===ACCOUNTANT_ID){getInterPersonRelations().forEach(relation=>{const debtor=group.members.find(member=>member.id===relation.debtorId),creditor=group.members.find(member=>member.id===relation.creditorId);if(debtor&&creditor)interItems.push(relationSummaryItem(debtor.id,creditor.id,`${escapeHtml(debtor.name)} owes ${escapeHtml(creditor.name)}`,relation.amount,"negative"))});group.members.forEach(member=>{const balance=balances.get(member.id),label=balance>0?`${escapeHtml(member.name)} gets back`:balance<0?`${escapeHtml(member.name)} owes`:`${escapeHtml(member.name)} is settled`,tone=balance>0?"positive":balance<0?"negative":"neutral";consolidatedItems.push(`<div class="balance-item"><div><strong>${label}</strong></div><b class="${tone}">${money(Math.abs(balance))}</b></div>`)})}else{const relations=getViewerRelations();group.members.filter(member=>member.id!==state.activeMemberId).forEach(member=>{const relation=relations.get(member.id);if(relation?.lent)interItems.push(relationSummaryItem(member.id,state.activeMemberId,`${escapeHtml(member.name)} owes you`,relation.lent,"positive"));if(relation?.owes)interItems.push(relationSummaryItem(state.activeMemberId,member.id,`You owe ${escapeHtml(member.name)}`,relation.owes,"negative"))});const balance=balances.get(state.activeMemberId)||0,label=balance>0?"You get back":balance<0?"You owe":"You are settled",tone=balance>0?"positive":balance<0?"negative":"neutral";consolidatedItems.push(`<div class="balance-item"><div><strong>${label}</strong></div><b class="${tone}">${money(Math.abs(balance))}</b></div>`)}$("#balance-list").innerHTML=summarySection("Inter-person",interItems,"No direct balances")+summarySection("Consolidated",consolidatedItems,"No balance");$("#balance-list").querySelectorAll("[data-relation-debtor]").forEach(button=>button.addEventListener("click",()=>openRelationSummary(button.dataset.relationDebtor,button.dataset.relationCreditor)));renderSettlements(balances)}
function getSettlementPayments(balances){const group=currentGroup(),creditors=group.members.map(member=>({...member,amount:balances.get(member.id)})).filter(person=>person.amount>0).sort((a,b)=>b.amount-a.amount),debtors=group.members.map(member=>({...member,amount:-balances.get(member.id)})).filter(person=>person.amount>0).sort((a,b)=>b.amount-a.amount),payments=[];let ci=0,di=0;while(ci<creditors.length&&di<debtors.length){const amount=Math.min(creditors[ci].amount,debtors[di].amount);if(amount)payments.push({from:debtors[di],to:creditors[ci],amount});creditors[ci].amount-=amount;debtors[di].amount-=amount;if(!creditors[ci].amount)ci++;if(!debtors[di].amount)di++}return payments}
function openSettlementForm(fromId=null,toId=null,amount=null){if(currentGroupIsReadOnly())return;const group=currentGroup(),recommendations=getSettlementPayments(getBalances()),suggestion=recommendations.find(payment=>payment.from.id===fromId&&payment.to.id===toId)||recommendations[0];if(!suggestion)return;const options=group.members.map(member=>`<option value="${member.id}">${escapeHtml(member.name)}</option>`).join("");$("#settlement-from").innerHTML=options;$("#settlement-to").innerHTML=options;$("#settlement-from").value=fromId||suggestion.from.id;$("#settlement-to").value=toId||suggestion.to.id;$("#settlement-amount").value=formatCentsForInput(amount||suggestion.amount);hideError("#settlement-error");$("#settlement-modal").hidden=false;document.body.classList.add("modal-open");if(window.matchMedia("(hover: hover) and (pointer: fine)").matches)$("#settlement-amount").focus()}
function closeSettlementForm(){$("#settlement-form").reset();$("#settlement-modal").hidden=true;document.body.classList.remove("modal-open");hideError("#settlement-error")}
function saveSettlementPayment(event){event.preventDefault();if(currentGroupIsReadOnly())return closeSettlementForm();const group=currentGroup(),fromId=$("#settlement-from").value,toId=$("#settlement-to").value,amount=parseMoneyToCents($("#settlement-amount").value),recommendation=getSettlementPayments(getBalances()).find(payment=>payment.from.id===fromId&&payment.to.id===toId);if(fromId===toId)return showError("#settlement-error","Choose two different members.");if(!Number.isFinite(amount)||amount<1)return showError("#settlement-error","Enter a valid payment amount.");if(!recommendation)return showError("#settlement-error","There is no recommended payment between these members.");if(amount>recommendation.amount)return showError("#settlement-error",`Payment cannot exceed ${money(recommendation.amount)}.`);const viewer=currentViewerSnapshot(group);group.payments=group.payments||[];group.payments.unshift({id:makeId(),fromId,toId,amount,date:today(),recordedAsId:viewer.id,recordedAsName:viewer.name,activityLog:[{action:"recorded",viewerId:viewer.id,viewerName:viewer.name,at:new Date().toISOString()}],createdAt:new Date().toISOString()});saveState();closeSettlementForm();renderTimeline();renderBalances()}
function openMemberBalanceSummary(memberId){const group=currentGroup(),member=group.members.find(item=>item.id===memberId);if(!member)return;const balances=getBalances(),balance=balances.get(memberId)||0,membersById=new Map(group.members.map(item=>[item.id,item])),direct=getInterPersonRelations().filter(relation=>relation.debtorId===memberId||relation.creditorId===memberId),payments=getSettlementPayments(balances).filter(payment=>payment.from.id===memberId||payment.to.id===memberId),directRows=direct.map(relation=>{const memberOwes=relation.debtorId===memberId,other=membersById.get(memberOwes?relation.creditorId:relation.debtorId),label=memberOwes?`${member.name} owes ${other?.name||"member"}`:`${other?.name||"Member"} owes ${member.name}`;return `<div class="relation-detail-row"><strong>${escapeHtml(label)}</strong><b>${money(relation.amount)}</b></div>`}).join(""),paymentRows=payments.map(payment=>`<div class="relation-detail-row"><strong>${escapeHtml(payment.from.name)} pays ${escapeHtml(payment.to.name)}</strong><b>${money(payment.amount)}</b></div>`).join("");$("#relation-kicker").textContent="MEMBER BALANCE";$("#relation-title").textContent=balance>0?`${member.name} gets back`:balance<0?`${member.name} owes`:`${member.name} is settled`;$("#relation-total").textContent=money(Math.abs(balance));$("#relation-details").innerHTML=`<section class="relation-date-group"><h3>Direct balances</h3><div>${directRows||'<div class="relation-detail-row"><strong>No direct balances</strong></div>'}</div></section><section class="relation-date-group"><h3>Settlement recommendation</h3><div>${paymentRows||'<div class="relation-detail-row"><strong>No payment needed</strong></div>'}</div></section>`;$("#relation-modal").hidden=false;document.body.classList.add("modal-open");$("#close-relation").focus()}
function renderSettlements(balances){const group=currentGroup(),recommendations=getSettlementPayments(balances),membersById=new Map(group.members.map(member=>[member.id,member])),readOnly=currentGroupIsReadOnly();$("#settlement-list").innerHTML=recommendations.length?recommendations.map(payment=>`<div class="settlement"><div><strong>${escapeHtml(payment.from.name)}</strong><span>pays</span><strong>${escapeHtml(payment.to.name)}</strong></div><b>${money(payment.amount)}</b>${readOnly?"":`<button class="record-settlement-button" type="button" data-settle-from="${payment.from.id}" data-settle-to="${payment.to.id}" data-settle-amount="${payment.amount}">Settle</button>`}</div>`).join(""):`<div class="all-set"><span>✓</span><p>${group.expenses.some(expense=>!expense.isDraft)?"Everyone is settled up.":"Settlements will appear here."}</p></div>`;$("#settlement-list").querySelectorAll("[data-settle-from]").forEach(button=>button.addEventListener("click",()=>openSettlementForm(button.dataset.settleFrom,button.dataset.settleTo,Number(button.dataset.settleAmount))));const recorded=group.payments||[];$("#settlement-history").innerHTML=recorded.length?recorded.map(payment=>{const from=membersById.get(payment.fromId),to=membersById.get(payment.toId);return `<div><span><strong>${escapeHtml(from?.name||"Member")}</strong> paid <strong>${escapeHtml(to?.name||"Member")}</strong><em>Recorded by ${escapeHtml(payment.recordedAsName||"Unknown viewer")}</em></span><b>${money(payment.amount)}</b></div>`}).join(""):""}

$("#group-form").addEventListener("submit",createGroup);$("#group-name").addEventListener("input",()=>hideError("#group-error"));$("#new-group-button").addEventListener("click",()=>showSetup());$("#cancel-group").addEventListener("click",showGroups);$("#back-to-groups").addEventListener("click",showGroups);$("#home-button").addEventListener("click",()=>state.groups.length?showGroups():showSetup());$("#add-test-day").addEventListener("click",()=>{const group=currentGroup();if(!group||currentGroupIsReadOnly())return;group.testOffset=(group.testOffset||0)+1;selectedDayDate=null;saveState();renderTrip()});$("#modal-backdrop").addEventListener("click",closeExpenseForm);$("#cancel-expense").addEventListener("click",closeExpenseForm);$("#expense-form").addEventListener("submit",addExpense);$("#save-draft-button").addEventListener("click",saveDraft);$("#expense-amount").addEventListener("input",handleExpenseAmountChange);$("#delete-backdrop").addEventListener("click",closeDeleteModal);$("#cancel-delete").addEventListener("click",closeDeleteModal);$("#confirm-delete").addEventListener("click",confirmDelete);document.addEventListener("keydown",event=>{if(event.key!=="Escape")return;if(!$("#delete-modal").hidden)closeDeleteModal();else if(!$("#expense-modal").hidden)closeExpenseForm()});
