$("#previous-day").addEventListener("click",()=>moveCarousel(-1));$("#next-day").addEventListener("click",()=>moveCarousel(1));const viewport=$(".day-viewport");viewport.addEventListener("touchstart",event=>{swipeStartX=event.changedTouches[0].clientX},{passive:true});viewport.addEventListener("touchend",event=>{if(swipeStartX===null)return;const distance=event.changedTouches[0].clientX-swipeStartX;if(Math.abs(distance)>45)moveCarousel(distance<0?1:-1);swipeStartX=null},{passive:true});window.addEventListener("resize",()=>{if(!$("#group-screen").hidden)updateCarousel()});
