function normalizeGroups(groups){return (groups||[]).map(group=>{group.visibility=group.visibility==="public"?"public":"private";group.expenses=group.expenses||[];group.deletedExpenses=group.deletedExpenses||[];group.payments=group.payments||[];group.testOffset=group.testOffset||0;group.expenses.forEach(expense=>{if(!expense.shares&&expense.participantIds?.length){const base=Math.floor(expense.amount/expense.participantIds.length),remainder=expense.amount-base*expense.participantIds.length;expense.shares=expense.participantIds.map((id,index)=>({id,amount:base+(index<remainder?1:0)}))}});return group})}
function applyFirebaseGroups(groups){const activeGroupId=state.activeGroupId,setupIsPristine=!editingGroupId&&!$("#group-name").value.trim()&&draftPeople.every(person=>!person.trim())&&document.querySelector('[name="group-visibility"]:checked')?.value==="private";state.groups=normalizeGroups(groups);if(!$("#groups-screen").hidden)renderGroups();else if(!$("#group-screen").hidden){if(state.groups.some(group=>group.id===activeGroupId))renderTrip();else showGroups()}else if(!$("#setup-screen").hidden&&state.groups.length&&setupIsPristine)showGroups()}
async function connectFirebase(){try{const{connectFirebaseStore}=await import("./firebase-store.js?v=4"),connection=await connectFirebaseStore(applyFirebaseGroups,showFirebaseError);firebaseStore=connection;$("#firebase-error").hidden=true;$("#new-group-button").hidden=false;applyFirebaseGroups(connection.groups);if(state.groups.length)showGroups();else{renderPeopleInputs();$("#groups-screen").hidden=true;$("#group-screen").hidden=true;$("#setup-screen").hidden=false}showInviteResult(connection.inviteResult)}catch(error){showFirebaseError(error);$("#groups-list").innerHTML='<p class="firebase-empty-state">Could not load trips from Firebase. Check your connection and reload.</p>'}}
function initializeApp(){["anti-buraot:v1","anti-buraot:v2","anti-buraot:firebase-uid"].forEach(key=>localStorage.removeItem(key));state.groups=[];$("#setup-screen").hidden=true;$("#group-screen").hidden=true;$("#groups-screen").hidden=false;$("#new-group-button").hidden=true;$("#groups-list").innerHTML='<p class="firebase-empty-state">Loading trips from Firebase…</p>';connectFirebase()}
initializeApp();
